*/



//----W-Craft WebSquare 변환 확인: include----//

//----W-Craft WebSquare 변환 확인: include----//

//----W-Craft WebSquare 변환 확인: include----//

//----W-Craft WebSquare 변환 확인: include----//

//----W-Craft WebSquare 변환 확인: include----//

//----W-Craft WebSquare 변환 확인: include----//
scwin.contnId;
scwin.notiObjSysCode;
scwin.vScrenID = "ULDSTF42040.gfm";

// scwin.onpageload, scwin.onpageunload 함수
scwin.onpageload = function() {
};

scwin.onpageunload = function() {
};

// WebSquare 컴포넌트 이벤트 함수
scwin.dts_noticeList_OnLoadCompleted = function(e) {

};

scwin.MxGrid_2_OnDblClick = async function(row, colid) {
    if (colid === 'SCREN_ID' || colid === 'MENU_NM') {
        scwin.contnId = dts_noticeList.getCellData(row, "SCREN_ID");

        //----W-Craft WebSquare 변환 확인: CreateDialogFrame----//
        const options = {
            id: "ULDMGT42045",
            title: "도움말 상세",
            type: "browserPopup",
            width: "660px",
            height: "290px"
        };

        const data = {
            // TO-DO : 팝업으로 전달할 파라미터 설정,
            callbackFn: "scwin.popupCallback"
        };

        const result = await $c.win.openPopup("ULDMGT42045.gfm", options, data);
        scwin.popupCallback(result);
        scwin.listSync();
    } else if (colid === 'SAVE_FILE_NM') {
        const screnId = dts_noticeList.getCellData(row, "SCREN_ID");
        location.href = "/scren.do?method=downloadHelpFile&V_SCREN_ID=" + screnId;
    }
};

scwin.bnt_Select_onclick = function(e) {
    scwin.listSync();
};

scwin.btn_New_onclick = async function(e) {
    scwin.contnId = "input";

    //----W-Craft WebSquare 변환 확인: CreateDialogFrame----//
    const options = {
        id: "ULDMGT42045",
        title: "도움말 상세",
        type: "browserPopup",
        width: "660px",
        height: "290px"
    };

    const data = {
        // TO-DO : 팝업으로 전달할 파라미터 설정,
        callbackFn: "scwin.popupCallback"
    };

    const result = await $c.win.openPopup("ULDMGT42045.gfm", options, data);
    scwin.popupCallback(result);
    scwin.listSync();
};

scwin.keyword_onkeydown = function(e) {
    if (e.keyCode === 13) {
        scwin.listSync();
    }
};

// 일반 함수
scwin.listSync = function() {
    const KeyWord = keyword.value;

    const Condition1 = MxCombo_1.getValue();
    // TODO Stage2: 0-based 검토
    const Condition2 = MxDataSet_code1.getCellData(cb_system_gbn.getSelectedIndex(), "CD_VAL");
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&keyword=" + KeyWord;
    url += "&Condition1=" + Condition1;
    url += "&Condition2=" + Condition2;
    const sbmOptions = {
        id : "sbm_dts_noticeList",
        action : "/scren.do",
        ref : "",
        target : "dts_noticeList=body.content",
        submitDoneHandler : scwin.dts_noticeList_OnLoadCompleted,
        isProcessMsg : false
    };

    $c.sbm.executeDynamic(sbmOptions);


};

scwin.code1Sync = function() {
    const sbmOptions = {
        id : "sbm_MxDataSet_code1",
        action : "/scren.do",
        ref : "",
        target : "MxDataSet_code1=body.content",
        // TODO Stage2: 원본 submission에 submitdone 없음
        submitDoneHandler : scwin.sbm_MxDataSet_code1_submitdone,
        isProcessMsg : false
    };

    $c.sbm.executeDynamic(sbmOptions);


};

scwin.setContnId = function(obj) {
    if (scwin.contnId !== "input") {
        scwin.contnId = dts_noticeList.getCellData(eval(obj), "SCREN_ID");
    }
};

scwin.getContnId = function() {
    return scwin.contnId;
};

scwin.setSysCode = function(obj) {
    scwin.notiObjSysCode = dts_noticeList.getCellData(eval(obj), "NOTI_OBJ_SYS_TP_CD");
};

scwin.getSysCode = function() {
    return scwin.notiObjSysCode;
};

scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_Top);
    scwin.listSync();
    const sbmOptions = {
        id : "sbm_MxDataSet_code1",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "MxDataSet_code1=body.content",
        // TODO Stage2: 원본 submission에 submitdone 없음
        submitDoneHandler : scwin.sbm_MxDataSet_code1_submitdone,
        isProcessMsg : false
    };

    $c.sbm.executeDynamic(sbmOptions);


    scwin.code1Sync();
    cb_system_gbn.Enable2 = true;
};

/**
 * @method
 * @name popupCallback
 * @description browserPopup 팝업의 callback 함수. 부모창에서 팝업 결과 값을 처리한다.
 * @param {String | Number} arg 팝업에서 전달받은 값
 */
scwin.popupCallback = function (arg) {
    // TO-DO : arg 값 확인 후 업무 로직 추가
};
